import 'dart:convert';
import 'dart:math';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitOrLoss;

  const Transaction({required this.coinName, required this.datetime, required this.profitOrLoss});
}

// Helper function to calculate average profit/loss for a list of transactions
double _calculateAverage(List<Transaction> transactions) {
  double sum = 0;
  int count = 0;
  for (var transaction in transactions) {
    sum += transaction.profitOrLoss;
    if (transaction.profitOrLoss != 0) {
      count++;
    }
  }
  return count == 0 ? 0 : sum / count;
}

// Function to find the top 3 coins with highest average profit
