  firstName: String,
  lastName: String,
});

const PersonModel = model('Person', PersonSchema);
export default PersonModel;
```

2. Use `SchemaFactory` in NestJS to create the models dynamically at runtime instead of hardcoding them as above. This is useful when you want to use different versions of the same schema across multiple parts of your application or when you need to generate the schema based on user input. Here's how you can do it:

```typescript
import { Injectable } from '@nestjs/common';
import { Model, SchemaFactory } from 'mongoose';
import { Address } from './address.dto';
import { Person } from './person.dto';

@Injectable()
export class UserModel {
  constructor(private readonly userModel: Model<UserDocument>) {}

  async findOne(filter: any): Promise<UserDocument> {
    return this.userModel.findOne(filter);
  }

  async create(data: any): Promise<UserDocument> {
    return new this.userModel(data).save();
  }
}

