To solve this problem, we will create a dictionary that maps each incorrect homophone to its correct replacement. Here's the code:

```swift
let incorrectHomophones = ["is": "are", "weigh": "weight", "too": "to", "no": "know", "see": "seem", "knot": "not"]

func replaceHomophones(text: String) -> String {
    var result = ""
    for (index, char) in text.characters.enumerate() {
        let wordStartIndex = result.characters.reverse().firstIndex(of: " ")?.offset(by: -1, from: result.endIndex) ?? text.characters.count
        let currentWordEndIndex = text.characters.index(of: " ", after: text.distance(from: text.startIndex, to: index)) ?? text.characters.index(before: text.endIndex)
        let currentWord = String(text[text.startIndex..<currentWordEndIndex])

        // Check if the current word contains any incorrect homophones
        let hasIncorrectHomophones = Set(incorrectHomophones.keys).intersection(Set(currentWord.split{$0 == " "}.map{String($0)})) != Set()

        // If so, replace them with their corresponding replacements
        if hasIncorrectHomophones {
            let correctedWord = String(currentWord.characters.enumerated().reduce("") { (result, (i, char)) -> String in
                let replacement = incorrectHomophones[String(char)]
                return replacement != nil ? String(result.prefix(upTo: i)) + replacement! + String(result.suffix(from: i)) : result + String(char)
            })

            result = String(result.prefix(upTo: wordStartIndex)) + String(correctedWord) + String(text[currentWordEndIndex...])
        } else {
            result += String(char)
        }
    }

    return result.reversed().joined()
}

