    % Calculate the number of dots and dashes in the sequence
    numDots = length(strfind(morseSequence, '.')) - 1;
    numDashes = length(strfind(morseSequence, '-')) - 1;

    % Update dot and dash counters based on the sequence
    dotCounter += numDots;
    dashCounter += numDashes;

    % Add spaces between characters and sequences
    if ~isempty(inputPhrase(i+1)) || i == length(inputPhrase)
        outputString = [outputString, num2str(dotCounter) '.' num2str(dashCounter) '- ', morseSequence, ' '];
        [dotCounter, dashCounter] = [0, 0];
    end
end

% Remove trailing spaces
outputString(end:-1:1, end) = '';

% Display the resulting Morse code representation
disp(outputString);
```

