```csharp
public decimal CalculateTotalPrice(decimal carPrice, decimal clothesPrice, decimal bookPrice)
{
    decimal totalClothesAndBooks = clothesPrice + bookPrice;
    decimal adjustedCarPrice = Math.Max(totalClothesAndBooks * 2, carPrice); // Adjust car price if necessary
    decimal totalPrice = adjustedCarPrice + clothesPrice + bookPrice;
    return totalPrice;
}
```

