function determineMostRelevantProtocol(inputData) {
  let relevanceA = 0;
  let relevanceB = 0;
  let relevanceC = 0;

  // Check for IPv6
  if (/^(?:[0-9a-fA-F]{1,4}:){7}(?:[0-9a-fA-F]{1,4}|:)$/.test(inputData.sourceIP)) {
    relevanceA += 97; // Higher weightage for IPv6
  }

  // Check for HTTP
  if (inputData.port === 80 || inputData.port === 443) {
    relevanceB += 97; // Higher weightage for HTTP
  }

  // Check for UDP
  if (inputData.protocol === 'UDP') {
    relevanceC += 97; // Higher weightage for UDP
  }

  // Calculate total relevance score
  const totalRelevance = relevanceA + relevanceB + relevanceC;

  // Return the protocol with highest relevance score
  return Math.max(...Object.values({ A: relevanceA, B: relevanceB, C: relevanceC })).name;
}

