  .then(data => {
    console.log(data);
  })
  .catch(error => {
    console.log

Here's a JavaScript function that takes a string variable in dot notation and returns all entries from an object where the nested key-value pair matches the given string:

```javascript
function findNestedEntries(obj, path, value) {
  let result = [];

  // Split the path into an array of keys
  const paths = path.split(".");

  // Recursive helper function to traverse the object and match values
  function traverse(o) {
    for (let i = 0; i < paths.length; i++) {
      const key = paths[i];
      if (!o.hasOwnProperty(key)) {
        // If we encounter a missing key, return null
        return null;
      }

      o = o[key];

      // If we reach the end of the path, check if the value matches
      if (i === paths.length - 1 && o === value) {
        result.push(o);
      }

      // If we have more keys to go, continue traversing
      if (o !== null && typeof o === "object") {
        const nestedResult = traverse(o);
        if (nestedResult !== null) {
          result.push(...nestedResult);
        }
      }
    }

    // Return null for leaf nodes with no further keys
    return null;
  }

  // Call the helper function to traverse the object
  traverse(obj);

  // Return the results
  return result;
}

